-- 데일리 미션 마스터 데이터 (21일 챌린지용)
-- Day 1-21 일차별 미션

BEGIN;

INSERT INTO daily_missions (day, title, description, verify_type, image_url, points, reason, method, is_active, created_at, updated_at) VALUES
(1, '햇빛 보며 산책하기', '오늘은 햇살 아래를 걸어볼까요? 따뜻한 햇살과 함께 걷는 시간은 마음까지 환하게 밝혀줘요.', 'PHOTO', 'https://cdn.imweb.me/thumbnail/20250624/a1bdba24fa18f.jpg', 100, '햇빛은 비타민 D 생성을 돕고, 스트레스를 줄여 피부 재생과 염증 완화에 효과적입니다.', '산책 중 자연 풍경이나 셀카 사진을 공유해주세요.', true, NOW(), NOW()),

(2, '10분 명상', '잠시 멈추고 조용히 눈을 감아보세요. 나에게 집중하는 10분이 오늘 하루를 바꿔줄 거예요.', 'PHOTO', 'https://cdn.imweb.me/thumbnail/20250624/7c984b9d7a047.jpg', 100, '명상은 스트레스를 완화하고 자율신경을 안정시켜 피부 염증 반응을 줄여줍니다.', '명상 공간, 타이머, 또는 앱 화면을 공유해주세요.', true, NOW(), NOW()),

(3, '허브티 한 잔 마시기', '커피 대신 따뜻한 허브티 한 잔으로 여유를 즐겨보세요. 은은한 향이 마음을 감싸줘요.', 'PHOTO', 'https://cdn.imweb.me/thumbnail/20250624/2960e048f7887.jpg', 100, '허브티는 항산화 효과가 있어 피부 진정과 트러블 완화에 도움을 줍니다.', '마신 허브티 사진이나 잔을 공유해주세요.', true, NOW(), NOW()),

(4, '수면 전 명상 음악', '오늘 밤은 음악과 함께 릴렉스하는 시간을 가져보세요. 부드러운 소리가 마음을 감싸 안아줄 거예요.', 'PHOTO', 'https://cdn.imweb.me/thumbnail/20250624/34d3be6c4e27f.jpg', 100, '수면 질 향상은 피부 재생을 촉진하고 야간 트러블 회복에도 도움이 됩니다.', '수면 음악 재생화면 또는 듣는 공간 사진을 공유해주세요.', true, NOW(), NOW()),

(5, '림프 순환', '다리를 벽에 기대고 5분간 휴식해보세요. 부기와 피로가 서서히 가라앉을 거예요.', 'PHOTO', 'https://cdn.imweb.me/thumbnail/20250624/bcd6f70b9850f.jpg', 100, '림프 순환을 도우면 노폐물 배출이 원활해지고 피부가 맑고 투명해져요.', '벽에 다리를 올린 자세 사진을 공유해주세요.', true, NOW(), NOW()),

(6, '미소 연습', '거울 앞에서 환하게 웃어볼까요? 작은 미소 하나가 하루를 바꾸기도 해요.', 'PHOTO', 'https://cdn.imweb.me/thumbnail/20250624/e07955d77dd71.jpg', 100, '웃음은 엔도르핀 분비를 촉진해 스트레스를 완화하고 피부 염증을 줄여줍니다.', '밝게 웃는 셀카를 공유해주세요.', true, NOW(), NOW()),

(7, '아침 감사 기록', '오늘 아침, 고마운 일 3가지를 떠올려보세요. 감사한 마음이 하루를 부드럽게 열어줘요.', 'TEXT', 'https://cdn.imweb.me/thumbnail/20250624/dcda59a723b6e.jpg', 100, '긍정 감정은 자율신경을 안정시켜 피부 컨디션을 개선하고 면역력을 높입니다.', '감사한 일 3가지를 작성해주세요.', true, NOW(), NOW()),

(8, '자연 속 산책하기', '숲길, 강가, 공원… 자연을 느낄 수 있는 곳에서 걸어보세요. 바람결과 햇살이 피부에도 스며들 거예요.', 'PHOTO', 'https://cdn.imweb.me/thumbnail/20250624/f83ffa59986cc.jpg', 100, '자연의 음이온은 스트레스를 낮추고 피부를 진정시키는 데 효과적입니다.', '자연 풍경이나 산책 중 셀카를 공유해주세요.', true, NOW(), NOW()),

(9, '10분 스트레칭', '몸이 뻐근할 땐 천천히 스트레칭을 해보세요. 근육과 마음이 함께 풀릴 거예요.', 'PHOTO', 'https://cdn.imweb.me/thumbnail/20250624/feab8d3de0a84.jpg', 100, '혈액순환이 개선되면 피부에 영양 공급이 원활해지고 생기 있는 피부로 이어집니다.', '스트레칭 자세나 운동 중 사진을 공유해주세요.', true, NOW(), NOW()),

(10, '맛있는 물 마시기', '오늘은 물을 맛있게 마셔볼까요? 따듯한 물에 소금한 꼬집 넣어서 마셔보세요.', 'PHOTO', 'https://cdn.imweb.me/thumbnail/20250624/3afc5fe0254a9.jpg', 100, '수분 섭취는 피부 보습을 유지하고, 노폐물 배출로 피부 컨디션을 맑게 합니다.', '맛있는 물 500ml 마신 컵 사진을 공유해주세요.', true, NOW(), NOW()),

(11, '수면 전 책 읽기', '잠들기 전 스마트폰 대신 책 한 권을 펼쳐보세요. 활자 속 여백이 하루를 정리해줘요.', 'PHOTO', 'https://cdn.imweb.me/thumbnail/20250624/a9a556ef2ef1e.jpg', 100, '전자기기 대신 책을 보면 멜라토닌 분비가 원활해져 수면 질이 높아지고 피부 회복에 좋습니다.', '책 표지나 독서 공간 사진을 공유해주세요.', true, NOW(), NOW()),

(12, '10분 명상', '잠시 멈추고 조용히 눈을 감아보세요. 나에게 집중하는 10분이 오늘 하루를 바꿔줄 거예요.', 'PHOTO', 'https://cdn.imweb.me/thumbnail/20250624/7c984b9d7a047.jpg', 100, '명상은 스트레스를 완화하고 자율신경을 안정시켜 피부 염증 반응을 줄여줍니다.', '명상 공간, 타이머, 또는 앱 화면을 공유해주세요.', true, NOW(), NOW()),

(13, '디지털 휴식', '전자기기 없이 30분을 보내보세요. 생각이 맑아지고 눈도 마음도 편안해질 거예요.', 'PHOTO', 'https://cdn.imweb.me/thumbnail/20250624/6b7c863c1ced7.jpg', 100, '블루라이트 노출을 줄이면 피부의 산화 스트레스를 완화하고 피부 탄력 유지에 도움을 줍니다.', '전자기기 없이 한 활동 사진(산책, 독서 등)을 공유해주세요.', true, NOW(), NOW()),

(14, '저녁 정리 시간', '하루를 돌아보며 오늘의 나를 정리해보세요. 작은 성취도 소중하게 느껴질 거예요.', 'TEXT', 'https://cdn.imweb.me/thumbnail/20250624/98ba1aef542d1.jpg', 100, '하루를 정리하며 자율신경을 안정시키면 숙면에 도움이 되고 피부 회복력이 향상됩니다.', '이번주를 정리하는 간단한 글을 써보세요.', true, NOW(), NOW()),

(15, '저강도 유산소', '가볍게 숨이 찰 정도로 움직여보세요. 땀이 살짝 맺히는 정도의 움직임이면 충분해요.', 'PHOTO', 'https://cdn.imweb.me/thumbnail/20250624/dfaa92c0f4e16.jpg', 100, '유산소 운동은 혈류를 원활히 해 피부에 산소와 영양을 충분히 전달해줍니다.', '만보계 캡처, 걷기나 자전거 타는 사진을 공유해주세요.', true, NOW(), NOW()),

(16, '림프 순환', '다리를 벽에 기대고 5분간 휴식해보세요. 부기와 피로가 서서히 가라앉을 거예요.', 'PHOTO', 'https://cdn.imweb.me/thumbnail/20250624/bcd6f70b9850f.jpg', 100, '림프 순환을 도우면 노폐물 배출이 원활해지고 피부가 맑고 투명해져요.', '벽에 다리를 올린 자세 사진을 공유해주세요.', true, NOW(), NOW()),

(17, '아침을 깨우는 물', '일어나자마자 마시는 물 한 잔이 하루의 리듬을 정리해줘요. 몸이 부드럽게 깨어날 거예요.', 'PHOTO', 'https://cdn.imweb.me/thumbnail/20250624/2cb014d826070.jpg', 100, '아침 수분 섭취는 밤새 잃은 수분을 보충해 피부 건조를 막고 유연성을 유지해줍니다.', '기상 후 물 500ml 마신 컵 사진을 공유해주세요.', true, NOW(), NOW()),

(18, '수면 전 물 한 잔', '자기 전 물 한 잔으로 하루를 정리해보세요. 과하지 않게, 부드럽게 마시는 게 포인트예요.', 'PHOTO', 'https://cdn.imweb.me/thumbnail/20250624/2fc1512802b37.jpg', 100, '수면 중 수분 공급은 탈수를 방지하고 아침의 푸석한 피부를 예방해줍니다.', '물컵 사진을 공유해주세요.', true, NOW(), NOW()),

(19, '10분 스트레칭', '몸이 뻐근할 땐 천천히 스트레칭을 해보세요. 근육과 마음이 함께 풀릴 거예요.', 'TEXT', 'https://cdn.imweb.me/thumbnail/20250624/feab8d3de0a84.jpg', 100, '혈액순환이 개선되면 피부에 영양 공급이 원활해지고 생기 있는 피부로 이어집니다.', '스트레칭 자세나 운동 중 사진을 공유해주세요.', true, NOW(), NOW()),

(20, '아침 햇빛 쬐기', '아침 햇살을 5분만 쬐어보세요. 몸도 마음도 자연스럽게 깨어납니다.', 'PHOTO', 'https://cdn.imweb.me/thumbnail/20250624/b9d0654af1a2b.jpg', 100, '아침 햇빛은 생체 리듬을 조절해 숙면과 피부 재생 리듬을 안정시켜줍니다.', '아침 햇살을 받는 풍경이나 셀카를 공유해주세요.', true, NOW(), NOW()),

(21, '3주간의 성취 돌아보기', '21일 동안의 나, 고생 많았어요. 기억에 남는 순간을 떠올려 정리해보세요.', 'TEXT', 'https://cdn.imweb.me/thumbnail/20250624/4ec9b440cde29.jpg', 100, '성취를 기록하면 긍정적인 감정이 형성되고 스트레스를 줄여 피부 컨디션 개선에 도움을 줍니다.', '챌린지 기간동안의 성취를 기록해주세요.', true, NOW(), NOW());

COMMIT;

